// src/components/CreateCliente.js
import React, { useState } from 'react';
import axios from 'axios';

const CreateCliente = ({ onCreate }) => {
  const [nome, setNome] = useState('');
  const [email, setEmail] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const response = await axios.post('http://localhost:8080/clientes', {
        nome,
        email,
      });

      // Atualiza a lista de clientes após a criação
      onCreate((prevClientes) => [...prevClientes, response.data]);

      // Limpar os campos
      setNome('');
      setEmail('');
    } catch (error) {
      console.error('Erro ao criar cliente', error);
    }
  };

  return (
    <div>
      <h2>Criar Cliente</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Nome"
          value={nome}
          onChange={(e) => setNome(e.target.value)}
        />
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
        <button type="submit">Criar Cliente</button>
      </form>
    </div>
  );
};

export default CreateCliente;
